package app.daybreak;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.webkit.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Theme-only QA on an owned disposable emulator. Never schedules or fires an alarm. */
public class KeyThemeQaTest extends Instrumentation {
 private Bundle args;private Activity activity;private WebView web;private int checks;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 private void check(boolean pass,String label)throws Exception{if(!pass)throw new Exception(label);checks++;Bundle s=new Bundle();s.putString("stage","PASS "+label);sendStatus(0,s);}
 private WebView find(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){WebView w=find(((ViewGroup)v).getChildAt(n));if(w!=null)return w;}return null;}
 private String js(String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] out={null};runOnMainSync(()->web.evaluateJavascript(code,r->{out[0]=r;latch.countDown();}));if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("JS timeout");return out[0];}
 private void await(Callable<Boolean> f)throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){if(f.call())return;Thread.sleep(100);}throw new Exception("State timeout");}
 private void launch()throws Exception{activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->web=find(activity.findViewById(android.R.id.content)));await(()->"true".equals(js("typeof st==='object'&&!!st&&!!st.settings")));}
 private void capture(String name)throws Exception{CountDownLatch ready=new CountDownLatch(1);runOnMainSync(()->web.postVisualStateCallback(System.nanoTime(),new WebView.VisualStateCallback(){public void onComplete(long id){web.invalidate();ready.countDown();}}));if(!ready.await(10,TimeUnit.SECONDS))throw new Exception("Visual state timeout");waitForIdleSync();Thread.sleep(1800);var b=getUiAutomation().takeScreenshot();var dir=new java.io.File(getTargetContext().getFilesDir(),"theme-qa");dir.mkdirs();try(var out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private Map<String,?> prefs(){var all=new HashMap<String,Object>(Store.p(getTargetContext()).getAll());all.remove("appearance");all.remove("iconDesign");return all;}
 private void fixture()throws Exception{Context c=getTargetContext();JSONObject custom=new JSONObject().put("id","custom:12345678-1234-1234-1234-123456789abc").put("name","Upgrade fixture").put("background","#102A36").put("primary","#43C7BD").put("secondary","#D79ABD").put("preferredText","#F7F1E8");Store.p(c).edit().putInt("playbackRevision",1).putBoolean("enabled",false).putInt("lead",37).putString("filter","theme QA fixture").putInt("snooze",11).putInt("volume",61).putInt("fade",120).putBoolean("vibrate",false).putBoolean("allDayEnabled",true).putInt("allDayMinutes",480).putString("appearance","ocean").putString("iconDesign","moon").putString("customThemes",new JSONArray().put(custom).toString()).commit();}
 public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();String mode=args.getString("mode","themes");
  if(mode.equals("seed")){launch();fixture();js("send('state')");check(Store.p(c).getInt("lead",0)==37,"Original 0.1.15 settings fixture saved");capture("before-upgrade");}
  else if(mode.equals("picker")){launch();js("page('settings');document.getElementById('themeSelect').focus()");
   String raw=js("JSON.stringify((()=>{const r=document.getElementById('themeSelect').getBoundingClientRect();return {x:(r.left+r.width/2)*devicePixelRatio,y:(r.top+r.height/2)*devicePixelRatio}})())");JSONObject point=new JSONObject(new org.json.JSONTokener(raw).nextValue().toString());int[] at=new int[2];runOnMainSync(()->web.getLocationOnScreen(at));float x=(float)point.getDouble("x")+at[0],y=(float)point.getDouble("y")+at[1];long now=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(android.view.MotionEvent.obtain(now,now,0,x,y,0),true);getUiAutomation().injectInputEvent(android.view.MotionEvent.obtain(now,now+100,1,x,y,0),true);Thread.sleep(700);capture("native-theme-dropdown");
   var root=getUiAutomation().getRootInActiveWindow();var options=root.findAccessibilityNodeInfosByText("Moonlit Orchid");check(!options.isEmpty(),"Native theme dropdown opens and exposes palette label");check(options.get(0).performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"Tap native Moonlit Orchid option");await(()->Appearance.current(c).id.equals("violet"));check("true".equals(js("document.getElementById('themeSelect').value==='violet'")),"Native popup tap persists and applies theme");capture("native-picker-selected");
  }
  else if(mode.equals("navigation")){launch();for(String id:new String[]{"rose","sage"}){js("document.getElementById('themeSelect').value='"+id+"';document.getElementById('themeSelect').dispatchEvent(new Event('change',{bubbles:true}))");await(()->Appearance.current(c).id.equals(id));for(String page:new String[]{"today","calendar","sounds","settings","appearance"}){js("page('"+page+"');document.getElementById('toast').classList.remove('visible')");check("true".equals(js("!document.getElementById('"+page+"').hidden&&document.documentElement.scrollWidth<=innerWidth")),"Navigation fits "+page+" in "+id);capture(page+"-"+id);}js("page('settings');document.getElementById('addManual').click()");check("true".equals(js("document.getElementById('manualDialog').open")),"Manual alarm dialog opens without scheduling in "+id);capture("manual-dialog-"+id);js("document.getElementById('manualDialog').close();page('appearance');document.getElementById('newCustomTheme').click()");check("true".equals(js("!document.getElementById('themeEditor').hidden")),"Custom editor retained in "+id);capture("editor-"+id);js("document.getElementById('cancelCustomTheme').click()");}js("document.getElementById('themeSelect').value='amethyst';document.getElementById('themeSelect').dispatchEvent(new Event('change',{bubbles:true}))");await(()->Appearance.current(c).id.equals("amethyst"));}
  else if(mode.equals("bars")){launch();js("page('settings')");Bundle state=new Bundle();runOnMainSync(()->{state.putString("stage","BAR appearance="+activity.getWindow().getInsetsController().getSystemBarsAppearance()+" decor="+activity.getWindow().getDecorView().getSystemUiVisibility());});sendStatus(0,state);capture("bars-diagnostic");Thread.sleep(10000);}
  else if(mode.equals("restore")){launch();check(Appearance.current(c).id.equals("amethyst"),"Amethyst selection survives Android force-stop and process relaunch");check(Appearance.icon(c).equals("moon"),"Icon selection survives process relaunch");check("true".equals(js("document.getElementById('themeSelect').value==='amethyst'&&document.documentElement.dataset.profile==='amethyst'")),"Relaunched native and WebView selection agree");js("page('settings')");capture("after-process-relaunch");}
  else {
   launch();check(Store.p(c).getInt("lead",0)==37&&Store.p(c).getInt("volume",0)==61&&Store.p(c).getInt("snooze",0)==11&&!Store.p(c).getBoolean("enabled",true),"0.1.15 upgrade preserves alarm/playback settings");check(Appearance.current(c).id.equals("ocean")&&Appearance.icon(c).equals("moon"),"Upgrade preserves theme and icon IDs");check(Appearance.customThemes(c).length()==1,"Upgrade preserves custom theme");
   Map<String,?> before=prefs();js("page('settings');document.getElementById('lead').value='39';document.getElementById('lead').dispatchEvent(new Event('input',{bubbles:true}))");
   check("true".equals(js("document.getElementById('themeSelect').options.length===17")),"Settings dropdown includes 16 built-ins plus saved custom theme");
   for(Appearance p:Appearance.ALL){
    js("document.getElementById('themeSelect').value='"+p.id+"';document.getElementById('themeSelect').dispatchEvent(new Event('change',{bubbles:true}))");
    await(()->Appearance.current(c).id.equals(p.id)&&"true".equals(js("document.documentElement.dataset.profile==='"+p.id+"'")));
    String hex=String.format("#%06X",p.background&0xFFFFFF);check("true".equals(js("getComputedStyle(document.documentElement).getPropertyValue('--paper').trim().toUpperCase()==='"+hex+"'&&document.getElementById('themeSelect').value==='"+p.id+"'")),"Rendered and persisted theme "+p.id);
    check("true".equals(js("document.documentElement.scrollWidth<=innerWidth&&document.getElementById('themeSelect').getBoundingClientRect().width>0")),"Settings fits viewport "+p.id);
    capture("settings-"+p.id);
    js("confirmAction('Remove custom theme?','Theme QA dialog fixture',()=>{});document.getElementById('yesConfirm').disabled=true");
    check("true".equals(js("(()=>{let d=getComputedStyle(document.getElementById('confirmDialog')),b=getComputedStyle(document.getElementById('yesConfirm'));return document.getElementById('confirmDialog').open&&d.backgroundColor===getComputedStyle(document.documentElement).backgroundColor&&b.opacity==='1'&&b.borderStyle==='dashed'})()")),"Dialog and disabled control use palette "+p.id);
    if(Arrays.asList("rose","sage","navy","lemon","cobalt","amethyst","graphite","pistachio").contains(p.id))capture("dialog-"+p.id);
    js("document.getElementById('yesConfirm').disabled=false;document.getElementById('confirmDialog').close()");
   }
   check("\"39\"".equals(js("document.getElementById('lead').value")),"Theme switching preserves unsaved settings input");check(before.equals(prefs()),"All stored nonappearance preferences preserved during 16 switches");
   js("page('appearance')");capture("appearance-amethyst");js("page('today')");capture("alarms-amethyst");
   check(Store.object(c,"manual").length()==0&&Store.object(c,"scheduled").length()==0&&Store.object(c,"current").length()==0,"No alarm scheduled or activated during QA");
  }
  if(activity!=null)runOnMainSync(activity::finish);result.putString("summary",checks+" "+mode+" checks passed");finish(Activity.RESULT_OK,result);
 }catch(Throwable t){result.putString("error",t.toString());finish(Activity.RESULT_CANCELED,result);}}
}
